```python
def fibonacci(n):
    if n <= 0:
        print("الرجاء إدخال عدد أكبر من الصفر.")
    elif n == 1:
        return 0
    elif n == 2:
        return 1
    else:
        a, b = 0, 1
        for _ in range(n - 2):
            a, b = b, a + b
        return b

